function ParkourRewardDialog:Awake()
    local parameters = self.controller.Argument.parameters
    self.activityData = checkTable(parameters.activityData)
    self.data = checkTable(parameters.data)
    CfUtils.SetActive(self.BtnRoleNameNode, false)
    --local activityContentId = checkNumber(self.activityData.activityContentId) ---排期表中的活动当id来用
    -----@type ActivityCakeBosScheduleVo
    --local scheduleVo = CfUtils.GetCfVo(AutoIds.IdSetting6456, "ActivityCakeBosScheduleVo", activityContentId)
    --CfUtils.FillImage(self.ImgBg, scheduleVo.modelId)

    if self.activityData.bgImage and not string.isEmpty(self.activityData.bgImage) then
        local bgImage = self.activityData.bgImage
        local path = CS.ParseUtils.ParsePathNameByData(bgImage)
        CfUtils.FillImage(self.ImgBg, path)
    end
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, 2592000, false, true)
end

function ParkourRewardDialog:FillTime()
    local serverTime = GameUtils.GetServerTime()
    local num = checkNumber(self.activityData.closeTime) - checkNumber(serverTime)
    if num < 0 then
        num = 0
    end
    CfUtils.FillText(self.Text2, CfUtils.GetTimeHMS4(num))
end

function ParkourRewardDialog:RefreshShow()
    GameUtils.Request("activityTinyWorld/task", {
        activityUuid = self.activityData.id, type = 2 }, Bind(self, self.TaskHomeResponseHandler))
end

function ParkourRewardDialog:TaskHomeResponseHandler(request, response)
    if checkInt(response.errCode) == 0 then
        self.taskData = response.data.tasks
        self.totalNum = self.taskData[#self.taskData].progress
        self.maxData = self.taskData[#self.taskData]
        table.remove(self.taskData, #self.taskData)
        table.sort(self.taskData, function(a, b)
            local aStatus = checkInt(a.status)
            local bStatus = checkInt(b.status)
            if aStatus == bStatus then
                return checkInt(a.id) < checkInt(b.id)
            else
                if aStatus == 1 then
                    return true
                elseif bStatus == 1 then
                    return false
                elseif aStatus == 2 then
                    return false
                elseif bStatus == 2 then
                    return true
                else
                    return false
                end
            end
        end)
        self:FillSelf()
    end
end

function ParkourRewardDialog:FillSelf()
    if #self.taskData > 0 then
        self:RefreshScoreShow()
    end

    self:FillTime()

    self:FillCellShow()

    self.TaskList:InitListView(table.count(self.taskData), Bind(self, self.OnGetItemByIndex))

    SetButtonAction(self.FontStyleButton, Bind(self, self.OneKeyReward))
    self:FilterProgress()
end

function ParkourRewardDialog:FilterProgress()
    local pro, count = 0, 0
    local redPoint = -1
    for i, v in pairs(self.taskData) do
        if checkNumber(v.status) == 2 then
            pro = pro + 1
        end
        if checkNumber(v.status) == 1 then
            redPoint = 1
        end
        count = count + 1
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainActivityMinWorldAchievementTask, redPoint)
    GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainActivityMinWorldAchievementTask)
    return { pro = pro, max = count }
end

function ParkourRewardDialog:FillCellShow()
    local count = #self.taskData
    local data = self.maxData
    local env = CfUtils.GetLuaScr(self.ResidentCell, UITaskCellPath)
    if isNotNull(env) then
        env:Refresh(data, Bind(self, self.OnMaxTaskCellClick), count, self.pointId)
    end
    CfUtils.SetActive(self.ResidentCell.gameObject, true)
end

function ParkourRewardDialog:RefreshScoreShow()
    if isNotNull(self.taskData) and  #self.taskData > 0 then
        local goodsId = checkNumber(self.data.scheduleConf.cornId)
        self.pointId = goodsId
        --local haveNo = GoodsUtils.GetThingNo(goodsId)
        --local photoPath = GoodsUtils.GetGoodsIconById(goodsId)
        --CfUtils.FillImage(self.ImgIcon, photoPath)
        local node = CfUtils.GetLuaScr(self.ImgIcon, "Game.Behaviours.CommonCurrencyNode")
        if isNotNull(node) then
            node:SetCurrencyShow(goodsId, self.totalNum)
        end
        --CfUtils.FillText(self.ImgIcon.transform.parent:Find("TexNumber"), haveNo)
    end
end

function ParkourRewardDialog:OneKeyReward()
    local isHaveReward = self:IsHaveTaskReward()
    if isHaveReward then
        local activityId = self.activityData.id
        local data = { activityUuid = activityId, taskId = 0, type = 2 }
        GameUtils.Request("activityTinyWorld/receiveTaskRewards", data, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            local rewards = checkTable(jsonData.rewards)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
            end
            self:RefreshTaskShow()
        end)
    else
        GameUtils.Toast(localize("暂无可领取的奖励"))
    end
end

function ParkourRewardDialog:RefreshTaskShow()
    for i, v in ipairs(self.taskData) do
        if v.status == 1 then
            v.status = 2
        end
    end

    if self.maxData.status == 1 then
        self.maxData.status = 2
    end

    self:RefreshScoreShow()
    GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
    self:FillCellShow()
    self:FilterProgress()
end

function ParkourRewardDialog:IsHaveTaskReward()
    for i, v in ipairs(self.taskData) do
        if v.status == 1 then
            return true
        end
    end

    if self.maxData.status == 1 then
        return true
    end
    return false
end

function ParkourRewardDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell.gameObject, UITaskCellPath)
    local data = self.taskData[index + 1]
    if scr then
        scr:Refresh(data, Bind(self, self.OnTaskCellClick), index + 1, self.pointId)
    end

    return cell
end

function ParkourRewardDialog:OnTaskCellClick(index)
    local data = self.taskData[index]
    if data.status == 2 then
        GameUtils.Toast(localize("奖励已领取"))
        return
    end
    if data.status == 1 then
        local activityId = self.activityData.id
        local serverData = { activityUuid = activityId, taskId = data.id, type = 2 }
        GameUtils.Request("activityTinyWorld/receiveTaskRewards", serverData, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            data.status = 2
            local rewards = checkTable(jsonData.rewards)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
            end
            self:RefreshScoreShow()
            GameUtils.ReloadData(self.TaskList, table.count(self.taskData))
            self:FillCellShow()
            self:FilterProgress()
        end)
    else
        GameUtils.Toast(localize("未达成领取条件"))
    end
end

function ParkourRewardDialog:OnMaxTaskCellClick()
    local data = self.maxData
    if data.status == 2 then
        GameUtils.Toast(localize("奖励已领取"))
        return
    end
    if data.status == 1 then
        local activityId = self.activityData.id
        local serverData = { activityUuid = activityId, taskId = data.id, type = 2 }
        GameUtils.Request("activityTinyWorld/receiveTaskRewards", serverData, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            data.status = 2
            local rewards = checkTable(jsonData.rewards)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
            end
            self:RefreshScoreShow()
            self:FillCellShow()
            self:FilterProgress()
        end)
    else
        GameUtils.Toast(localize("未达成领取条件"))
    end
end

